class NPCTrainer < Trainer
  attr_accessor :version
  attr_accessor :items
  attr_accessor :lose_text
  attr_accessor :win_text

  def initialize(name, trainer_type, version = 0)
    super(name, trainer_type)
    @version   = version
    @items     = []
    @lose_text = nil
    @win_text  = nil
  end
end

def level
  @level = growth_rate.level_from_exp(@exp) if !@level
  return @level
end

# Sets this Pokémon's level. The given level must be between 1 and the
# maximum level (defined in {GameData::GrowthRate}).
# @param value [Integer] new level (between 1 and the maximum level)
def level=(value)
  if value < 1 || value > GameData::GrowthRate.max_level
    raise ArgumentError.new(_INTL("The level number ({1}) is invalid.", value))
  end
  @exp = growth_rate.minimum_exp_for_level(value)
  @level = value
end

# Sets this Pokémon's Exp. Points.
# @param value [Integer] new experience points
def exp=(value)
  @exp = value
  @level = nil
end

def initialize(species, level, owner = $player, withMoves = true, recheck_form = true)
  species_data = GameData::Species.get(species)
  @species          = species_data.species
  @form             = species_data.base_form
  @forced_form      = nil
  @time_form_set    = nil
  self.level        = level
  @steps_to_hatch   = 0
  heal_status
  @gender           = nil
  @shiny            = nil
  @ability_index    = nil
  @ability          = nil
  @nature           = nil
  @nature_for_stats = nil
  @item             = nil
  @mail             = nil
  @moves            = []
  reset_moves if withMoves
  @first_moves      = []
  @ribbons          = []
  @cool             = 0
  @beauty           = 0
  @cute             = 0
  @smart            = 0
  @tough            = 0
  @sheen            = 0
  @pokerus          = 0
  @name             = nil
  @happiness        = species_data.happiness
  @poke_ball        = :POKEBALL
  @markings         = []
  @iv               = {}
  @ivMaxed          = {}
  @ev               = {}
  GameData::Stat.each_main do |s|
    @iv[s.id]       = rand(IV_STAT_LIMIT + 1)
    @ev[s.id]       = 0
  end
  case owner
  when Owner
    @owner = owner
  when Player, NPCTrainer
    @owner = Owner.new_from_trainer(owner)
  else
    @owner = Owner.new(0, "", 2, 2)
  end
  @obtain_method    = 0   # Met
  @obtain_method    = 4 if $game_switches && $game_switches[Settings::FATEFUL_ENCOUNTER_SWITCH]
  @obtain_map       = ($game_map) ? $game_map.map_id : 0
  @obtain_text      = nil
  @obtain_level     = level
  @hatched_map      = 0
  @timeReceived     = Time.now.to_i
  @timeEggHatched   = nil
  @fused            = nil
  @personalID       = rand(2**16) | (rand(2**16) << 16)
  @hp               = 1
  @totalhp          = 1
  calc_stats
  if @form == 0 && recheck_form
    f = MultipleForms.call("getFormOnCreation", self)
    if f
      self.form = f
      reset_moves if withMoves
    end
  end
end
